import{_ as t,o as r,c as e,ai as n}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"C# 语言总结","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/csharp/language.md","filePath":"tech-system/backend/csharp/language.md"}'),l={name:"tech-system/backend/csharp/language.md"};function o(i,a,s,d,h,c){return r(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="c-语言总结" tabindex="-1">C# 语言总结 <a class="header-anchor" href="#c-语言总结" aria-label="Permalink to “C# 语言总结”">​</a></h1><blockquote><p>我对 C# 的定位：<strong>侧翼技能</strong>——补 Windows / .NET 生态与本地中小、工控旁路场景；<strong>不替代 Java 主栈</strong>。</p></blockquote><hr><h2 id="c-的核心特点-在我眼里" tabindex="-1">C# 的核心特点（在我眼里） <a class="header-anchor" href="#c-的核心特点-在我眼里" aria-label="Permalink to “C# 的核心特点（在我眼里）”">​</a></h2><ul><li>和 Java 同属 <strong>强类型 OO 企业语言</strong>，迁移成本低</li><li>绑在 <strong>.NET</strong> 上：Web、桌面、部分工控上位机一条链</li><li>语法比老 Java 更「现代」一点（async、LINQ、属性等），但本质仍是工程交付</li><li>Windows 生态里存量项目多，洛阳制造向信息化更容易撞上</li></ul><p>一句话：C# 卖的是 <strong>.NET 与 Windows 场景覆盖</strong>，不是让我换主粮。</p><hr><h2 id="运行时我怎么看" tabindex="-1">运行时我怎么看 <a class="header-anchor" href="#运行时我怎么看" aria-label="Permalink to “运行时我怎么看”">​</a></h2><ul><li>现代主线是 <strong>.NET</strong>（跨平台）；老项目仍大量 <strong>.NET Framework</strong>（偏 Windows）</li><li>对中小交付：能分清新旧项目跑在哪套 runtime，比背语法重要</li><li>和 JVM 类似：语言是 C#，平台是 CLR/.NET</li></ul><hr><h2 id="适合什么-不适合什么" tabindex="-1">适合什么 / 不适合什么 <a class="header-anchor" href="#适合什么-不适合什么" aria-label="Permalink to “适合什么 / 不适合什么”">​</a></h2><table tabindex="0"><thead><tr><th>适合</th><th>不适合（对我而言）</th></tr></thead><tbody><tr><td>Windows 桌面工具、WinForm/WPF 上位机</td><td>用 C# 重写已有 Java 主业务</td></tr><tr><td>维护/二开本地 .NET 信息化</td><td>当大厂八股主战场</td></tr><tr><td>部分 ASP.NET 中小 Web</td><td>和 Electron 抢「所有桌面」（能 Electron 就不必强上）</td></tr><tr><td>远程 .NET 维护类岗位的入门筹码</td><td>AI 胶水首选（仍让 Python）</td></tr></tbody></table><hr><h2 id="我为什么学-c" tabindex="-1">我为什么学 C# <a class="header-anchor" href="#我为什么学-c" aria-label="Permalink to “我为什么学 C#”">​</a></h2><ol><li><strong>洛阳 / 制造向中小</strong>：Windows + 上位机/.NET 存量真实存在</li><li>有 Java 底子，语言本身不难，难在 <strong>生态与老项目</strong></li><li>与 Java 分工：Java 扛 Web 主域；C# 扛撞上的 Windows/.NET 活</li><li>篇数保持薄：够接、够改、够讲清判断即可</li></ol><p>框架 → <a href="./frameworks.html">C# / .NET 框架总结</a></p>',16)])])}const m=t(l,[["render",o]]);export{b as __pageData,m as default};
